# Excel to CSV Converter using Qt5

Here's a complete C++ program using Qt5 that creates a GUI application to convert Excel files to CSV format:

```cpp
#include <QApplication>
#include <QMainWindow>
#include <QPushButton>
#include <QFileDialog>
#include <QVBoxLayout>
#include <QMessageBox>
#include <QDir>
#include <QProcess>
#include <QDebug>

class ExcelToCsvConverter : public QMainWindow {
    Q_OBJECT

public:
    ExcelToCsvConverter(QWidget *parent = nullptr) : QMainWindow(parent) {
        // Set up the main window
        setWindowTitle("Excel to CSV Converter");
        setFixedSize(400, 200);

        // Create widgets
        QWidget *centralWidget = new QWidget(this);
        QVBoxLayout *layout = new QVBoxLayout(centralWidget);

        selectButton = new QPushButton("Select Directory", this);
        convertButton = new QPushButton("Convert Excel to CSV", this);
        statusLabel = new QLabel("Select a directory containing Excel files", this);

        // Disable convert button initially
        convertButton->setEnabled(false);

        // Add widgets to layout
        layout->addWidget(statusLabel);
        layout->addWidget(selectButton);
        layout->addWidget(convertButton);
        layout->addStretch();

        setCentralWidget(centralWidget);

        // Connect signals
        connect(selectButton, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
        connect(convertButton, &QPushButton::clicked, this, &ExcelToCsvConverter::convertFiles);
    }

private slots:
    void selectDirectory() {
        QString dir = QFileDialog::getExistingDirectory(this, "Select Directory",
                                                      QDir::homePath(),
                                                      QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

        if (!dir.isEmpty()) {
            selectedDirectory = dir;
            statusLabel->setText("Selected: " + dir);
            convertButton->setEnabled(true);
        }
    }

    void convertFiles() {
        if (selectedDirectory.isEmpty()) {
            QMessageBox::warning(this, "Error", "No directory selected!");
            return;
        }

        // Create output directory
        QDir outputDir(selectedDirectory + "/csv_output");
        if (!outputDir.exists()) {
            if (!outputDir.mkpath(".")) {
                QMessageBox::critical(this, "Error", "Failed to create output directory!");
                return;
            }
        }

        // Find all Excel files in the directory
        QDir dir(selectedDirectory);
        QStringList filters;
        filters << "*.xls" << "*.xlsx";
        QStringList excelFiles = dir.entryList(filters, QDir::Files);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "Info", "No Excel files found in the selected directory.");
            return;
        }

        // Process each Excel file
        int successCount = 0;
        int failCount = 0;

        for (const QString &file : excelFiles) {
            QString inputPath = selectedDirectory + "/" + file;
            QString outputPath = outputDir.absolutePath() + "/" + QFileInfo(file).baseName() + ".csv";

            // Use libreoffice in headless mode to convert the file
            QProcess process;
            QStringList args;
            args << "--headless" << "--convert-to" << "csv" << "--outdir" << outputDir.absolutePath() << inputPath;

            process.start("libreoffice", args);

            if (!process.waitForFinished(-1)) {
                qDebug() << "Conversion failed for" << file;
                failCount++;
            } else {
                successCount++;
            }
        }

        // Show results
        QString message = QString("Conversion complete!\n\n")
                + QString("Successfully converted: %1 files\n").arg(successCount)
                + QString("Failed to convert: %1 files\n").arg(failCount)
                + QString("\nCSV files saved to:\n%1").arg(outputDir.absolutePath());

        QMessageBox::information(this, "Conversion Complete", message);
    }

private:
    QPushButton *selectButton;
    QPushButton *convertButton;
    QLabel *statusLabel;
    QString selectedDirectory;
};

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    // Check if libreoffice is available
    if (QProcess::execute("which", {"libreoffice"}) != 0) {
        QMessageBox::critical(nullptr, "Error",
            "LibreOffice is required but not found.\n"
            "Please install LibreOffice to use this application.");
        return 1;
    }

    ExcelToCsvConverter converter;
    converter.show();

    return app.exec();
}

#include "main.moc"
```

## How to Use This Program

1. **Prerequisites**:
   - Qt5 development libraries installed
   - LibreOffice installed (for the actual conversion)
   - C++ compiler with Qt support

2. **Compilation**:
   - Save this code to a file (e.g., `excel_to_csv.cpp`)
   - Compile with: `qmake -project && qmake && make`

3. **Usage**:
   - Run the compiled executable
   - Click "Select Directory" to choose a folder containing Excel files
   - Click "Convert Excel to CSV" to convert all Excel files to CSV format
   - The CSV files will be saved in a new "csv_output" subdirectory

## Notes

1. This program uses LibreOffice in headless mode to perform the actual conversion. Make sure LibreOffice is installed on your system.

2. The program handles both `.xls` and `.xlsx` file formats.

3. The GUI is simple but functional, with status messages and error handling.

4. For Windows users, you might need to adjust the LibreOffice command or path in the code.

5. If you want to use a different conversion method (like a specific library), you would need to modify the conversion logic in the `convertFiles()` method.

